import struct


def pack_header(version, msg_type, length):
    return struct.pack(">BBH", version, msg_type, length)


def unpack_header(data):
    return struct.unpack(">BBH", data)


def pack_point(x, y):
    return struct.pack("<ff", x, y)


def read_records(data, fmt):
    size = struct.calcsize(fmt)
    for offset in range(0, len(data), size):
        chunk = data[offset:offset + size]
        if len(chunk) == size:
            yield struct.unpack(fmt, chunk)
